  if (refunds.some((r) => r.productId === productId)) throw conflict('line has already been refunded');
  const refund = { productId, amount: line.net - line.discount + line.tax, createdAt: ctx.clock.now().toISOString() };
  ctx.store.invoices.update(id, { refunds: [...refunds, refund] });
  return refund;
}
